-- P00 · Confirmar o alvo ANTES de instalar (AFONSO Staging, nunca a V1).
-- Qualquer FALHA => PARAR. Não instalar.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH pt AS (SELECT c.oid, c.relname::text AS nome FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p', 'v', 'm', 'f')),
pf AS (SELECT p.oid, p.proname::text AS nome, p.pronargs, p.prosrc, p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public'),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'P00-01'::text, 'existe public.staging_notes (marca do staging)'::text, (to_regclass('public.staging_notes') IS NOT NULL)::boolean, 'sim'::text, (CASE WHEN to_regclass('public.staging_notes') IS NULL THEN 'não' ELSE 'sim' END || ' (sessão ' || current_user || ', read_only=' || current_setting('transaction_read_only') || ')')::text
  UNION ALL SELECT 'P00-02'::text, 'public tem exatamente staging_notes e user_roles'::text, (coalesce((SELECT array_agg(nome ORDER BY nome COLLATE "C") FROM pt), '{}') = ARRAY['staging_notes', 'user_roles'])::boolean, 'staging_notes,user_roles'::text, ((SELECT string_agg(nome, ',' ORDER BY nome COLLATE "C") FROM pt))::text
  UNION ALL SELECT 'P00-03'::text, 'nenhuma tabela V2 existe ainda'::text, (NOT EXISTS (SELECT 1 FROM pt WHERE nome = ANY (ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[])))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM pt WHERE nome = ANY (ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[])), 'nenhuma'))::text
  UNION ALL SELECT 'P00-04'::text, 'nenhuma função V2 existe ainda'::text, (NOT EXISTS (SELECT 1 FROM pf WHERE nome = ANY (ARRAY['access_invites_pilot_guard', 'account_access_on_new_profile', 'audit_sensitive_write', 'claim_inbound_message', 'claim_pending_confirmation', 'consultant_preferences_track_opt_ins', 'consume_access_invite', 'content_access_consents_validate', 'conversation_states_touch', 'daily_digests_validate', 'effective_tier', 'email_drafts_validate', 'expire_beta_testers', 'handle_new_user', 'is_admin', 'issue_pilot_invite', 'issue_referral_invite', 'mark_pending_presented', 'merge_accounts_apply', 'merge_accounts_preview', 'pending_actions_validate', 'people_touch_email_norm', 'pilot_participant_on_invite_used', 'pilot_participants_guard', 'plan_configs_validate', 'product_feedback_validate', 'product_updates_validate', 'profiles_restrict_self_update', 'profiles_validate_billing', 'purge_admin_audit_logs', 'release_conversation_lock', 'release_pending_confirmation', 'release_unsolicited_slot', 'reminders_sync_follow_up_id', 'reserve_unsolicited_slot', 'revoke_pilot_invite', 'set_updated_at', 'subscription_events_validate', 'text_norm', 'tier_at_least', 'try_acquire_conversation_lock']::text[])))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM pf WHERE nome = ANY (ARRAY['access_invites_pilot_guard', 'account_access_on_new_profile', 'audit_sensitive_write', 'claim_inbound_message', 'claim_pending_confirmation', 'consultant_preferences_track_opt_ins', 'consume_access_invite', 'content_access_consents_validate', 'conversation_states_touch', 'daily_digests_validate', 'effective_tier', 'email_drafts_validate', 'expire_beta_testers', 'handle_new_user', 'is_admin', 'issue_pilot_invite', 'issue_referral_invite', 'mark_pending_presented', 'merge_accounts_apply', 'merge_accounts_preview', 'pending_actions_validate', 'people_touch_email_norm', 'pilot_participant_on_invite_used', 'pilot_participants_guard', 'plan_configs_validate', 'product_feedback_validate', 'product_updates_validate', 'profiles_restrict_self_update', 'profiles_validate_billing', 'purge_admin_audit_logs', 'release_conversation_lock', 'release_pending_confirmation', 'release_unsolicited_slot', 'reminders_sync_follow_up_id', 'reserve_unsolicited_slot', 'revoke_pilot_invite', 'set_updated_at', 'subscription_events_validate', 'text_norm', 'tier_at_least', 'try_acquire_conversation_lock']::text[])), 'nenhuma'))::text
  UNION ALL SELECT 'P00-05'::text, 'nenhum tipo V2 existe ainda'::text, (NOT EXISTS (SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname::text = ANY (ARRAY['assistant_correction_category', 'assistant_reflection_trigger', 'deal_stage', 'person_role', 'prospecting_listing_type', 'prospecting_source_type', 'prospecting_status']::text[])))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(t.typname::text, ',') FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname::text = ANY (ARRAY['assistant_correction_category', 'assistant_reflection_trigger', 'deal_stage', 'person_role', 'prospecting_listing_type', 'prospecting_source_type', 'prospecting_status']::text[])), 'nenhum'))::text
  UNION ALL SELECT 'P00-06'::text, 'PostgreSQL 15 ou superior'::text, (current_setting('server_version_num')::int >= 150000)::boolean, '>= 150000'::text, (current_setting('server_version'))::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 6 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
